import Component from '@glimmer/component';
import { service } from '@glimmer/core';
import { action } from '@ember/tracked-decorator';
import { later } from '@ember/runloop';

export default class CsvDownloaderComponent extends Component {
  @service()
  worker;

  url = '';
  downloading = false;
  error = null;
  progress = 0;

  constructor() {
    super(...arguments);
  }

  @action
  startDownload() {
    this.error = null;
    this.downloading = true;
    this.progress = 0;

    if (!this.url) {
      this.error = "Please enter a URL.";
      this.downloading = false;
      return;
    }

    this.worker.postMessage({ url: this.url });
  }

  @action
  stopDownload() {
    this.worker.postMessage({ terminate: true });
    this.downloading = false;
    this.error = null;
    this.progress = 0;
  }

  didReceiveMessage(event) {
    const message = event.data;

    switch (message.type) {
      case 'progress':
        this.progress = message.progress;
        break;
      case 'success':
        this.downloading = false;
        // Trigger a download of the CSV data
        const blob = new Blob([message.data], { type: 'text/csv' });
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'data.csv'; // You can customize the filename
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        window.URL.revokeObjectURL(url);
        break;
      case 'error':
        this.error = message.error;
        this.downloading = false;
        break;
    }
  }
}
