    const data1 = XLSX.utils.sheet_to_json(sheet1);
    const data2 = XLSX.utils.sheet_to_json(sheet2);

    const discrepancies = [];

    if (data1.length !== data2.length) {
      console.warn("Files have different number of rows.  Comparison may be inaccurate.");
    }

    for (let i = 0; i < data1.length; i++) {
      const row1 = data1[i];
      const row2 = data2[i];

      for (const column in row1) {
        if (row1.hasOwnProperty(column)) {
          const value1 = row1[column];
          const value2 = row2[column];

          if (value1 !== value2) {
            discrepancies.push({
              row: i + 1,
              column: column,
              file1Value: value1,
              file2Value: value2,
            });
          }
        }
      }
    }

    return discrepancies;
  } catch (error) {
